#include <exception>
#include <functional>
#include <map>
#include <string>
#include <vector>

class PluginGuard
{
public:
    explicit PluginGuard(int maxFailures) : m_max{ maxFailures } {}

    bool call(const std::string& plugin, const std::function<void()>& fn)
    {
        if (disabled(plugin)) return false;
        try
        {
            fn();
            return true;
        }
        catch (const std::exception& e) { record(plugin, e.what()); }
        catch (...) { record(plugin, "unknown error"); }
        return false;
    }

    bool disabled(const std::string& plugin) const
    {
        const auto it{ m_state.find(plugin) };
        return it != m_state.end() && it->second.failures >= m_max;
    }

    int failures(const std::string& plugin) const
    {
        const auto it{ m_state.find(plugin) };
        return it == m_state.end() ? 0 : it->second.failures;
    }

    std::string lastError(const std::string& plugin) const
    {
        const auto it{ m_state.find(plugin) };
        return it == m_state.end() ? "" : it->second.last;
    }

    std::vector<std::string> report() const
    {
        std::vector<std::string> lines;
        for (const auto& [name, s] : m_state)
            if (s.failures > 0)
                lines.push_back(name + ": " + std::to_string(s.failures) + " failure(s), last: " + s.last + (disabled(name) ? " (disabled)" : ""));
        return lines;
    }

private:
    struct State { int failures{ 0 }; std::string last; };
    void record(const std::string& plugin, const std::string& message) { State& s{ m_state[plugin] }; ++s.failures; s.last = message; }

    int m_max;
    std::map<std::string, State> m_state;
};

unitTests:
#include <stdexcept>
TEST("successful calls run") { PluginGuard g{ 3 }; int runs{ 0 }; CHECK(g.call("a", [&] { ++runs; })); CHECK_EQ(runs, 1); CHECK_EQ(g.failures("a"), 0); }
TEST("exceptions are caught and recorded") { PluginGuard g{ 3 }; CHECK(!g.call("lantern", [] { throw std::runtime_error{ "no fuel" }; })); CHECK_EQ(g.failures("lantern"), 1); CHECK_EQ(g.lastError("lantern"), std::string("no fuel")); }
TEST("non-standard exceptions too") { PluginGuard g{ 3 }; g.call("x", [] { throw 42; }); CHECK_EQ(g.lastError("x"), std::string("unknown error")); }
TEST("disabled after too many failures")
{
    PluginGuard g{ 2 }; int runs{ 0 };
    auto bad = [&] { ++runs; throw std::runtime_error{ "boom" }; };
    g.call("p", bad); CHECK(!g.disabled("p"));
    g.call("p", bad); CHECK(g.disabled("p"));
    CHECK(!g.call("p", [&] { ++runs; }));
    CHECK_EQ(runs, 2);
}
TEST("other plugins are unaffected") { PluginGuard g{ 1 }; g.call("bad", [] { throw std::runtime_error{ "x" }; }); CHECK(g.call("good", [] {})); CHECK(!g.disabled("good")); }
TEST("the report")
{
    PluginGuard g{ 2 };
    g.call("zeta", [] { throw std::runtime_error{ "one" }; });
    g.call("alpha", [] { throw std::runtime_error{ "a" }; });
    g.call("alpha", [] { throw std::runtime_error{ "b" }; });
    g.call("fine", [] {});
    CHECK(g.report() == std::vector<std::string>({ "alpha: 2 failure(s), last: b (disabled)", "zeta: 1 failure(s), last: one" }));
}

